ReveImageCreateNode.schema:
IO.Schema(node_id='ReveImageCreateNode', display_name='Reve Image Create', category='partner/image/Reve', description='Generate images from text descriptions using Reve.', inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Text description of the desired image. Maximum 2560 characters.'), IO.DynamicCombo.Input('model', options=_model_inputs(['reve-create@20250915'], aspect_ratios=['3:2', '16:9', '9:16', '2:3', '4:3', '3:4', '1:1']), tooltip='Model version to use for generation.'), *_postprocessing_inputs(), IO.Int.Input('seed', default=0, min=0, max=2147483647, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.')], outputs=[IO.Image.Output()], hidden=[IO.Hidden.auth_token_sim_org, IO.Hidden.api_key_sim_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['upscale', 'upscale.upscale_factor']), expr='
                (
                    $factor := $lookup(widgets, "upscale.upscale_factor");
                    $fmt := {"approximate": true, "note": "(base)"};
                    widgets.upscale = "enabled" ? (
                        $factor = 4 ? {"type": "usd", "usd": 0.0762, "format": $fmt}
                        : $factor = 3 ? {"type": "usd", "usd": 0.0591, "format": $fmt}
                        : {"type": "usd", "usd": 0.0457, "format": $fmt}
                    ) : {"type": "usd", "usd": 0.03432, "format": $fmt}
                )
                '))

